/**
 * Versioned questionnaire schema.
 *
 * Phase 8 implements the questionnaire state machine and Phase 9 the AYUSH modules.
 * Phase 1 only records the invariant that governs both: clinical content is versioned,
 * named-approved configuration — never code, and never generated by a model at runtime.
 */

/** Answer states a patient may always choose. Patients are never forced to guess. */
export const NON_COMMITTAL_ANSWERS = [
  'NOT_SURE',
  'PREFER_TO_DISCUSS_WITH_DOCTOR',
  'NOT_APPLICABLE',
] as const;

export type NonCommittalAnswer = (typeof NON_COMMITTAL_ANSWERS)[number];

/** Identifies exactly which approved content version produced a stored answer. */
export interface QuestionnaireVersionRef {
  /** Governance registry id of the published questionnaire. */
  readonly questionnaireId: string;
  /** Semantic version of the published content. */
  readonly version: string;
  /** ISO-8601 date the version became effective. */
  readonly effectiveFrom: string;
}
